def mod_inverse(a, b):
    if a == 0 or b == 0:
        raise ValueError("Input must be non-zero.")
    if a > b:
        a, b = b, a

    x, y, x1, y1 = 0, 1, 1, 0
    while b != 0:
        q = a // b
        a, b = b, a % b
        x, x1 = x1 - q * x, x
        y, y1 = y1 - q * y, y

    if x < 0:
        x += b

    return x

def mod_inverse(a, b):
    if b == 0:
        return None

    x, y, x_old, y_old = 0, 1, 1, 0
    while b:
        quotient = a // b
        a, b = b, a % b
        x, y = y_old, x_old - quotient * y_old
        x_old, y_old = y, x

    if x < 0:
        return x + b
    return x

