def next_permutation(perm: list) -> bool:
    # Find the first position from the right where perm[i] < perm[i+1]
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            # Find the rightmost element in perm[i+1:] that is greater than perm[i]
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    # Swap perm[i] and perm[j]
                    perm[i], perm[j] = perm[j], perm[i]
                    break
            # Reverse the elements in perm[i+1:] to get the next permutation
            perm[i + 1:] = sorted(perm[i + 1:])
            return True
    # If no such pair is found, the last permutation is reached
    return False

